{"command": "psql -X -c "
-- Cost of the losing (seq-scan-on-orders) plan for comparison:
SET enable_bitmapscan = off;
EXPLAIN (COSTS ON)
SELECT p.category, SUM(oi.quantity * oi.unit_price) AS revenue, COUNT(*) AS line_count
FROM order_items oi JOIN orders o ON o.order_id = oi.order_id
JOIN products p ON p.product_id = oi.product_id
WHERE o.status = 'COMPLETED' AND o.order_date >= DATE '2026-01-01'
GROUP BY p.category ORDER BY revenue DESC;
" 2>&1 | tail -30", "workdir": "/work"}

