INSERT INTO order_items (order_item_id, order_id, product_id, quantity, unit_price)
SELECT i.order_item_id, i.order_id, i.product_id, i.quantity, p.unit_price
FROM _gen_items i
JOIN products p ON p.product_id = i.product_id
ORDER BY i.order_id, i.order_item_id;

-- 2g. Staging tables are session-local; drop them now that the real tables
--     are loaded and consistent.
DROP TABLE _gen_orders;
DROP TABLE _gen_items;
